struct StateLifetime {
    var storedCount = 1

    mutating func update(reset: Bool) {
        if reset {
            storedCount = 0
        } else {
            storedCount += 1
        }
    }
}

var state = StateLifetime()
state.update(reset: false)
state.update(reset: false)
print("State: \(state.storedCount)")

